cd /work/submit && python3 - <<'PY'
s=open('planb64.cpp').read()
old = """        const Span pf{rec.addr, rec.addr_len};
        size_t slash = 0;
        size_t slashes = 0;
        for (size_t i = 0; i < pf.n; ++i) {
            if (pf.p[i] == '/') {
                if (slashes == 0) slash = i;
                ++slashes;
            }
        }
        if (slashes != 1)
            fail("FIB " + quote(path) + ": malformed prefix '" +
                 std::string(pf.p, pf.n) + "'");
        uint64_t len = 0;
        if (!parse_dec(pf.p + slash + 1, pf.n - slash - 1, kMaxPrefixLen, len))
            fail("FIB " + quote(path) + ": prefix length must be 0..64 ('" +
                 std::string(pf.p + slash + 1, pf.n - slash - 1) + "')");
        size_t alen = slash;
        if (alen + 1 > sizeof(addr)) fail("FIB " + quote(path) + ": address too long");
        if (alen != 0) std::memcpy(addr, pf.p, alen);
        addr[alen] = '\\0';"""
new = """        // The prefix length field contains decimal digits only; a second '/'
        // inside it is rejected here, as is an empty or oversized field.
        uint64_t len = 0;
        if (!parse_dec(rec.len, rec.len_len, kMaxPrefixLen, len))
            fail("FIB " + quote(path) + ": prefix length must be 0..64 ('" +
                 std::string(rec.len, rec.len_len) + "')");
        const size_t alen = rec.addr_len;
        if (alen + 1 > sizeof(addr)) fail("FIB " + quote(path) + ": address too long");
        if (alen != 0) std::memcpy(addr, rec.addr, alen);
        addr[alen] = '\\0';"""
assert old in s
s=s.replace(old,new)
open('planb64.cpp','w').write(s)
PY
